codes.cpp:
#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> numbers = {1, 2, 3, 4};
    vector<int> squares;
    for (int n : numbers) {
        squares.push_back(n * n);
    }
    cout << "[";
    for (size_t i = 0; i < squares.size(); i++) {
        cout << squares[i];
        if (i + 1 < squares.size()) cout << ", ";
    }
    cout << "]" << endl;     // [1, 4, 9, 16]
    return 0;
}

